package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;

/** A claim as the screen shows it: the amount with two decimals, the date as yyyy-MM-dd, the status by name,
 * the number null unless it has one, the due fixed at settling (two decimals) or null while it is live,
 * the user who opened it or null while it is a draft, whether a statement bound it and the figure it bound
 * it to (two decimals; null: n/a), and the number of the claim a correction corrects (null: not a correction), and its due-by fixed when it was created (yyyy-MM-dd), and its status log, oldest first, and the date it is deferred until (yyyy-MM-dd; null: never deferred), and how many proofs it has been given, and the number of the claim it was split off (null: none), and the user whose open editor locks it (null: not locked), and whether it is a late entry (added while its period was soft-closed), and the last day it was reminded (yyyy-MM-dd; null: never). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status, String number,
        String due, String openedBy, boolean stated, String statedDue, String corrects, String dueBy,
        List<LogLine> log, String deferredUntil, int proofs, String splitFrom, String lockedBy,
        boolean lateEntry, String reminded) {

    /** A line of the status log: the status, the user who gave it, the sheet's today then and the due then. */
    public record LogLine(String status, String by, String date, String due) {
    }

    public static ClaimResponse from(Claim claim, List<ClaimLogLine> log) {
        return from(claim, log, null, false, null);
    }

    public static ClaimResponse from(Claim claim, List<ClaimLogLine> log, String lockedBy, boolean lateEntry,
            LocalDate reminded) {
        return new ClaimResponse(claim.id(), claim.personId(), claim.amount().toPlainString(),
                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
                claim.due() == null ? null : claim.due().setScale(2).toPlainString(), claim.openedBy(),
                claim.stated(), claim.statedDue() == null ? null : claim.statedDue().setScale(2).toPlainString(),
                claim.corrects(), claim.dueBy().toString(),
                log.stream().map((l) -> new LogLine(l.status().name(), l.by(), l.date().toString(), l.due())).toList(),
                claim.deferredUntil() == null ? null : claim.deferredUntil().toString(),
                claim.proofs(), claim.splitFrom(), lockedBy, lateEntry,
                reminded == null ? null : reminded.toString());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Refuses (400) a correction unless the number it corrects is a SETTLED claim of the same person. */
public class CheckClaimInputCorrects {
    public void check(@Val ClaimInput input, @Val Person person, ClaimRepository claims) throws InvalidClaimException {
        if (input.corrects() == null) {
            return;
        }
        boolean settled = claims.findForPerson(person.sheetId(), person.id()).stream()
                .anyMatch(c -> input.corrects().equals(c.number()) && c.status() == ClaimStatus.SETTLED);
        if (!settled) {
            throw new InvalidClaimException(
                    "A correction must name a settled claim of " + person.name() + "; no settled claim " + input.corrects() + ".");
        }
    }
}
# Add a claim to a person; an amount that is missing, negative or has more than two decimals, or a bad date, is refused (400). A blank date is the sheet's today.
# A claim whose due-by (its date plus the terms it would get) falls inside a closed period, or after its person's retirement date, is refused (400).
# A negative amount (a correction) is refused (400) unless it names, by number, a SETTLED claim of the same person.
