package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Refuses (400) a new claim whose external reference another claim on the sheet already has, ignoring case. */
public class CheckClaimInputRef {
    public void check(@Val ClaimInput input, @Val Person person, ClaimRepository claims) throws InvalidClaimException {
        check(input.ref(), person.sheetId(), null, claims);
    }

    /** Refuses the reference (null: none) when a claim on the sheet other than {@code except} (null: none) has it. */
    public static void check(String ref, String sheetId, Long except, ClaimRepository claims) throws InvalidClaimException {
        if (ref != null && claims.refUsed(sheetId, ref, except)) {
            throw new InvalidClaimException("The reference " + ref + " is already used on the sheet.");
        }
    }
}
